import sys

def compute_z_array(s):
    """Compute Z array for string s"""
    n = len(s)
    if n == 0:
        return []
    z = [0] * n
    z[0] = n
    l, r = 0, 0

    for i in range(1, n):
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l, r = i, i + z[i] - 1
    return z

def find_pattern_occurrences(text, pattern):
    """Find all starting indices of pattern in text using Z algorithm"""
    if len(pattern) == 0:
        return list(range(len(text) + 1))
    if len(pattern) > len(text):
        return []

    # Create combined string: pattern + '#' + text
    combined = pattern + '#' + text
    z = compute_z_array(combined)

    # Find occurrences where Z value equals pattern length
    occurrences = []
    pattern_len = len(pattern)
    for i in range(pattern_len + 1, len(combined)):
        if z[i] == pattern_len:
            # Convert to index in original text
            text_index = i - pattern_len - 1
            occurrences.append(text_index)

    return occurrences

def main():
    # Read input
    text = sys.stdin.readline().rstrip('\n')
    pattern = sys.stdin.readline().rstrip('\n')

    # Find occurrences
    occurrences = find_pattern_occurrences(text, pattern)

    # Print output
    if occurrences:
        print(' '.join(map(str, occurrences)))
    else:
        print()

if __name__ == "__main__":
    main()
